import{_ as a,o,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const l="/assets/225_591fe9ae-e090-4e82-9d9a-2e535b78126b.6RLewUQu.png",d="/assets/216_blobid16.q9x58nm-.png",m=JSON.parse('{"title":"物理服务器救援模式操作","description":"","frontmatter":{"title":"物理服务器救援模式操作"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/rescue-mode-operations.md","filePath":"ops-knowledge-base/dedicated-server/rescue-mode-operations.md","lastUpdated":1788259091000}'),s={name:"ops-knowledge-base/dedicated-server/rescue-mode-operations.md"};function r(n,e,c,p,u,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="一、功能介绍" tabindex="-1">一、功能介绍 <a class="header-anchor" href="#一、功能介绍" aria-label="Permalink to &quot;一、功能介绍&quot;">​</a></h2><p>当服务器出现故障，如系统崩溃无法正常进入系统，但系统内有需要备份的数据时，可使用救援系统功能。救援系统支持 Linux 和 Windows 两种操作系统，能在系统异常时，将服务器启动到对应救援模式，以便用户备份重要数据。</p><h2 id="二、操作入口" tabindex="-1">二、操作入口 <a class="header-anchor" href="#二、操作入口" aria-label="Permalink to &quot;二、操作入口&quot;">​</a></h2><ol><li>登录平台，进入客户中心，下方**“我的订单”** 点击 **“物理服务器”**。或者在 **“产品管理”** 点击 **“物理服务器”**，根据机器所在地区和状态筛选。</li><li>在产品列表中，找到目标服务器，点击进入 **“产品详情”** 页面。</li><li>在 “服务器信息” 标签页下，找到并点击 **“救援系统”** 按钮，弹出 “救援系统” 操作窗口。</li></ol><p><img src="'+l+'" alt=""></p><h2 id="三、操作步骤" tabindex="-1">三、操作步骤 <a class="header-anchor" href="#三、操作步骤" aria-label="Permalink to &quot;三、操作步骤&quot;">​</a></h2><h3 id="一-选择救援系统类型" tabindex="-1">（一）选择救援系统类型 <a class="header-anchor" href="#一-选择救援系统类型" aria-label="Permalink to &quot;（一）选择救援系统类型&quot;">​</a></h3><p>在 “救援系统” 窗口中，根据服务器原本的操作系统类型，选择对应的救援系统：</p><ul><li>若服务器为 Linux 系统，选择 **“Linux”**；</li><li>若服务器为 Windows 系统，选择 **“Windows”**。</li></ul><h3 id="二-数据备份操作-以-linux-救援系统为例" tabindex="-1">（二）数据备份操作（以 Linux 救援系统为例） <a class="header-anchor" href="#二-数据备份操作-以-linux-救援系统为例" aria-label="Permalink to &quot;（二）数据备份操作（以 Linux 救援系统为例）&quot;">​</a></h3><ol><li>进入 Linux 救援系统后，后台会自动显示用户和密码，可使用该信息进行远程登录。</li><li>登录后，执行<code>lsblk</code>或<code>df -Th</code>命令，查看系统分区及是否挂载。</li><li>若分区未挂载，需手动进行挂载操作（例如：<code>mount /dev/sda1 /mnt</code>，将<code>/dev/sda1</code>分区挂载到<code>/mnt</code>目录）。</li><li>挂载完成后，查看对应分区是否有需要备份的数据。</li><li>完成数据备份后，您可根据需求选择重装系统，以便继续使用服务器开展业务</li></ol><p><img src="'+d+'" alt=""></p>',12)])])}const b=a(s,[["render",r]]);export{m as __pageData,b as default};
